// Transparent OpenAI-compatible shim for the DAEMONS AI-play harness.
//
// The harness (Clad3815/gpt-play-pokemon-firered, patched to honour
// OPENAI_BASE_URL) posts a normal /v1/chat/completions body here. This does NOT
// rewrite its prompts -- it forwards them and gets out of the way -- because
// duplicating the agent's prompting means maintaining two brains and this one
// would silently drift from theirs on every upstream change.
//
// What it DOES add: the shared-secret check, a model default, and a marker so
// the reasoning line can be lifted out downstream for the console and the voice.
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};
const expected = $env.DEX_SHARED_SECRET;
if (expected && headers['x-dex-secret'] !== expected) {
  throw new Error('Unauthorized: bad or missing x-dex-secret');
}
const messages = Array.isArray(body.messages) ? body.messages : [];
if (!messages.length) throw new Error('Missing messages');

// Does this call carry a screenshot? The harness reads RAM, so images are the
// exception -- an explicit "look at the screen" rather than every turn.
const hasImage = messages.some(m => Array.isArray(m.content)
  && m.content.some(c => c && c.type === 'image_url'));

const completionBody = {
  model: body.model || (hasImage ? ($env.DAEMONS_VISION_MODEL || 'default')
                                 : ($env.DAEMONS_LLM_MODEL || 'default')),
  messages,
  max_tokens: body.max_tokens || 600,
  temperature: body.temperature ?? 0.4,
  stream: false,
};
// reasoning_effort / reasoning_summary are OpenAI-only. Lenient servers ignore
// them, strict ones return 400 -- so they are dropped rather than forwarded.
return [{ json: { completionBody, hasImage, speak: body.speak === true,
                  voice: body.voice || 'index' } }];

// OpenAI-compatible in, OpenAI-compatible out. The harness parses this the
// same way it parses api.openai.com, so the shim stays invisible to it.
const r = $input.first().json;
const content = r?.choices?.[0]?.message?.content ?? r?.message?.content ?? '';
const text = String(content).trim();

// THE THOUGHT, FOR THE CONSOLE. The interesting thing in these runs is not the
// button, it is the one line of reasoning before it -- so it is pulled out here
// rather than left buried in the payload. Two shapes are tried: a labelled
// line, then the first sentence. Never invented if absent.
let thought = null;
const m = text.match(/^\s*(?:thought|reasoning|thinking|plan)\s*[:\-]\s*(.+)$/im);
if (m) thought = m[1].trim();
else {
  const first = text.split(/\n/).map(s => s.trim()).filter(Boolean)[0] || '';
  if (first && first.length <= 240 && !first.startsWith('{')) thought = first;
}
if (thought) thought = thought.slice(0, 240);

return [{ json: { text, thought, upstream: r,
                  speak: $('Validate + Build').first().json.speak,
                  voice: $('Validate + Build').first().json.voice } }];

// Rebuild the OpenAI response the harness expects, and hang our extras off it.
// Anything OpenAI would not have sent lives under `daemons` so a future
// upstream change cannot collide with it.
const p = $('Parse + Extract Thought').first().json;
let audioBase64 = null;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf && buf.length) audioBase64 = buf.toString('base64');
} catch (e) { /* no TTS this turn -- the console line still prints */ }
const up = p.upstream || {};
return [{ json: {
  id: up.id || 'daemons-shim',
  object: 'chat.completion',
  created: Math.floor(Date.now() / 1000),
  model: up.model || 'local',
  choices: [{ index: 0, message: { role: 'assistant', content: p.text },
              finish_reason: (up.choices && up.choices[0] && up.choices[0].finish_reason) || 'stop' }],
  usage: up.usage || {},
  daemons: { thought: p.thought, audioBase64,
             audioMime: audioBase64 ? 'audio/mpeg' : null },
} }];
